pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target) internal {
        target = address(this);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        try c.sendMoney(target, 0, "") {} catch { return; }
        assertTrue(c.depositsCount() == countBefore && address(c).balance == balBefore);
    }

    function testFuzz_run(address target) public {
        _run(target);
    }

    receive() external payable {}
}
